head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// inputType="custom" Column 의 Cell 구성 정보를 반환한다. (custom Column 이 정상 렌더되도록 text 로 구성)
scwin.target1_customTypeGetter = function (info) {
    return { "id" : "cell_custom_" + info.rowIndex + "_" + info.colIndex, "inputType" : "text", "options" : {} };
};

// 서버로 실제 전송된 파라미터를 가로채 기록한다.
//  다운로드는 숨겨진 iframe 으로 form 전송되고 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 submit 을 감싸 전달값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.gVar = { body : "" };

scwin.hookRequest = function () {
    scwin.gVar = { body : "" };

    var fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            var objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
};

// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (strKey) {
    var strBody = scwin.gVar.body || "";
    var nKey = strBody.indexOf("hashkey='" + strKey + "'");
    if (nKey < 0) return "(미전달)";

    var strRest = strBody.substring(nKey);
    var nVal = strRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    strRest = strRest.substring(nVal + 7);
    return strRest.substring(0, strRest.indexOf("'"));
};

// customToDataType 값을 골라 Excel 파일을 내려받는다.
scwin.download = function (strValue, strDesc) {
    var objTarget = $p.getComponentById("target1");
    var objOptions = { fileName : "customToDataType_" + strDesc, extension : "xlsx" };
    if (strValue !== "") {
        objOptions.customToDataType = strValue;
    }

    scwin.hookRequest();
    try {
        objTarget.advancedExcelDownload(objOptions);
    } finally {
        scwin.gVar.unhook();
    }

    scwin.setReturnValue("----- customToDataType " + strDesc + " -----");
    scwin.setReturnValue("    전달 옵션 : " + (strValue === "" ? "{} (customToDataType 생략)" : "{ customToDataType : '" + strValue + "' }"));
    scwin.setReturnValue("    서버 전달값 : customToDataType=" + scwin.getSentValue("customToDataType"));
    scwin.setReturnValue("    받은 파일 : customToDataType_" + strDesc + ".xlsx");
    scwin.setReturnValue("");
};

scwin.btn_unset_onclick = function (e) { scwin.download("", "unset"); };
scwin.btn_false_onclick = function (e) { scwin.download("false", "false"); };
scwin.btn_true_onclick  = function (e) { scwin.download("true", "true"); };
